INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextID`,`comment`) VALUES
(28444,0,0,'%s calls upon the mighty armies of the Scourge!',42,0,100,1,0,0,28683,'Highlord Darion Mograine'),
(28444,1,0,'Armies of the Scourge, hear my call! The scarlet apocalypse has begun! Tear this land asunder and leave only death in your wake!',14,0,100,22,0,0,28684,'Highlord Darion Mograine'),
(28907,0,0,'The sky itself feeds upon the suffering of the conquered!',12,0,100,5,0,0,29048,'Prince Valanar'),
(28907,1,0,'The Scarlet Crusade is powerless to stop us!',12,0,100,5,0,0,29049,'Prince Valanar'),
(28907,2,0,'The corpses of those that try only serve to feed our expanding host!',12,0,100,1,0,0,29050,'Prince Valanar'),
(28907,3,0,'The Scarlet fleet lies in ruin upon the sundered coast!',12,0,100,25,0,0,29051,'Prince Valanar'),
(28907,4,0,'With each enemy slain, our strength grows! We mustn''t relent!',12,0,100,5,0,0,29052,'Prince Valanar'),
(28907,5,0,'The Lich King has spoken to each of you! Let his words resonate among you once more!',12,0,100,25,0,0,29053,'Prince Valanar'),
(28907,6,0,'ALL. MUST. DIE.',12,0,100,22,0,0,29054,'Prince Valanar'),
(28907,7,0,'Leave no survivors in your wake, brothers and sisters!',12,0,100,274,0,0,29055,'Prince Valanar'),
(28907,8,0,'No mercy for the weak!',12,0,100,15,0,0,29056,'Prince Valanar'),
(28907,9,0,'TERROR!',12,0,100,5,0,0,29057,'Prince Valanar'),
(28907,10,0,'CHAOS!',12,0,100,22,0,0,29058,'Prince Valanar'),
(28907,11,0,'DESTRUCTION!',12,0,100,15,0,0,29059,'Prince Valanar'),
(28907,12,0,'With the approaching darkness comes the end of the Scarlet Crusade. You will battle once more! For the Scourge! For the Lich King!',12,0,100,5,0,0,29060,'Prince Valanar'),
(28907,13,0,'SUFFER WELL, DEATH KNIGHTS!',12,0,100,71,0,9006,29061,'Prince Valanar');
