INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextID`,`comment`) VALUES
(27928,0,0,'You can leave my sight, squire, before I slay you. Again.',12,0,100,0,0,0,28104,'Siouxsie the Banshee'),
(27928,0,1,'No. Away with you, worm.',12,0,100,0,0,0,28105,'Siouxsie the Banshee'),
(27928,0,2,'Get away from me, Edwards, lest I behead you.',12,0,100,0,0,0,28102,'Siouxsie the Banshee'),
(28486,0,0,'M-mistress... might I b-brush your mighty steed...?',12,0,100,0,0,0,28098,'Squire Edwards'),
(28486,0,1,'M-mistress... may I p-polish your armor...?',12,0,100,0,0,0,28097,'Squire Edwards'),
(28486,0,2,'M-mistress... did you n-need more corpse dust, p-perhaps...?',12,0,100,0,0,0,28100,'Squire Edwards'),
(28486,1,0,'Yes, M-mistress...',12,0,100,0,0,0,28101,'Squire Edwards');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextID`,`comment`) VALUES
(28611,0,0,'The Crusade will be victorious!',12,0,100,0,0,0,29717,'Scarlet Captain'),
(28611,0,1,'Let the purging begin!',12,0,100,0,0,0,29720,'Scarlet Captain'),
(28611,0,2,'You''re not welcome in these lands, monster!',12,0,100,0,0,0,29719,'Scarlet Captain'),
(28611,0,3,'Scourge filth! DIE!',12,0,100,0,0,0,28597,'Scarlet Captain - On Aggro'),
(28611,0,4,'I will present your head to Abbendis myself!',12,0,100,0,0,0,28599,'Scarlet Captain - On Aggro'),
(28611,0,5,'By the Light be cleansed!',12,0,100,0,0,0,28602,'Scarlet Captain - On Aggro'),
(29061,0,0,'Come to finish the job, have you?',12,0,100,0,0,0,29393,'special_surprise SAY_EXEC_START_1'),
(29061,1,0,'Come to finish the job, have ye?',12,0,100,0,0,0,29335,'special_surprise SAY_EXEC_START_2'),
(29061,2,0,'Come ta finish da job, mon?',12,0,100,0,0,0,29403,'special_surprise SAY_EXEC_START_3'),
(29061,3,0,'You''ll look me in the eyes when...',12,0,100,0,0,0,29369,'special_surprise SAY_EXEC_PROG_1'),
(29061,4,0,'Well this son o'' Ironforge would like...',12,0,100,0,0,0,29336,'special_surprise SAY_EXEC_PROG_2'),
(29061,5,0,'Ironic, isn''t it? To be killed...',12,0,100,0,0,0,29394,'special_surprise SAY_EXEC_PROG_3'),
(29061,6,0,'If you''d allow me just one...',12,0,100,0,0,0,29348,'special_surprise SAY_EXEC_PROG_4'),
(29061,7,0,'I''d like to stand for...',12,0,100,0,0,0,29323,'special_surprise SAY_EXEC_PROG_5'),
(29061,8,0,'I want to die like an orc...',12,0,100,0,0,0,29384,'special_surprise SAY_EXEC_PROG_6'),
(29061,9,0,'Dis troll gonna stand for da...',12,0,100,0,0,0,29404,'special_surprise SAY_EXEC_PROG_7'),
(29061,10,0,'$n?',12,0,100,0,0,0,29395,'special_surprise SAY_EXEC_NAME_1'),
(29061,11,0,'$n? Mon?',12,0,100,0,0,0,29405,'special_surprise SAY_EXEC_NAME_2'),
(29061,12,0,'$n, I''d recognize that face anywhere... What... What have they done to you, $n?',12,0,100,0,0,0,29386,'special_surprise SAY_EXEC_RECOG_1'),
(29061,13,0,'$n, I''d recognize those face tentacles anywhere... What... What have they done to you, $n?',12,0,100,0,0,0,29360,'special_surprise SAY_EXEC_RECOG_2'),
(29061,14,0,'$n, I''d recognize that face anywhere... What... What have they done to ye, $g lad:lass;?',12,0,100,0,0,0,29338,'special_surprise SAY_EXEC_RECOG_3'),
(29061,15,0,'$n, I''d recognize that decay anywhere... What... What have they done to you, $n?',12,0,100,0,0,0,29396,'special_surprise SAY_EXEC_RECOG_4'),
(29061,16,0,'$n, I''d recognize those horns anywhere... What... What have they done to you, $n?',12,0,100,0,0,0,29289,'special_surprise SAY_EXEC_RECOG_5'),
(29061,17,0,'$n, I''d recognize dem tusks anywhere... What... What have dey done ta you, mon?',12,0,100,0,0,0,29406,'special_surprise SAY_EXEC_RECOG_6'),
(29061,18,0,'You don''t remember me, do you? Blasted Scourge... They''ve tried to drain you of everything that made you a righteous force of reckoning. Every last ounce of good... Everything that made you a draenei!',12,0,100,0,0,0,29361,'special_surprise SAY_EXEC_NOREM_1'),
(29061,19,0,'Ye don''t remember me, do ye? Blasted Scourge... They''ve tried to drain ye o'' everything that made ye a righteous force o'' reckoning. Every last ounce o'' good... Everything that made ye a $g son:daughter; o'' Ironforge!',12,0,100,0,0,0,29339,'special_surprise SAY_EXEC_NOREM_2'),
(29061,20,0,'You don''t remember me? We were humans once - long, long ago - until Lordaeron fell to the Scourge. Your transformation to a Scourge zombie came shortly after my own. Not long after that, our minds were freed by the Dark Lady.',12,0,100,0,0,0,29397,'special_surprise SAY_EXEC_NOREM_3'),
(29061,21,0,'You don''t remember me, do you? Blasted Scourge... They''ve tried to drain you of everything that made you a pint-sized force of reckoning. Every last ounce of good... Everything that made you a gnome!',12,0,100,0,0,0,29351,'special_surprise SAY_EXEC_NOREM_4'),
(29061,22,0,'You don''t remember me, do you? Blasted Scourge... They''ve tried to drain you of everything that made you a righteous force of reckoning. Every last ounce of good... Everything that made you a human!',12,0,100,0,0,0,29314,'special_surprise SAY_EXEC_NOREM_5'),
(29061,23,0,'You don''t remember me? When you were a child your mother would leave you in my care while she served at the Temple of the Moon. I held you in my arms and fed you honey and sheep''s milk to calm you until she would return. You were my little angel. Blasted Scourge... What have they done to you, $n?',12,0,100,0,0,0,29326,'special_surprise SAY_EXEC_NOREM_6'),
(29061,24,0,'You don''t remember me, do you? Blasted Scourge... They''ve tried to drain you of everything that made you a righteous force of reckoning. Every last ounce of good... Everything that made you an orc!',12,0,100,0,0,0,29387,'special_surprise SAY_EXEC_NOREM_7'),
(29061,25,0,'You don''t remember me, do you? Blasted Scourge... They''ve tried to drain you of everything that made you a righteous force of reckoning. Every last ounce of good... Everything that made you a tauren!',12,0,100,0,0,0,29290,'special_surprise SAY_EXEC_NOREM_8'),
(29061,26,0,'You don''t remember me, mon? Damn da Scourge! Dey gone ta drain you of everytin'' dat made ya a mojo masta. Every last ounce a good... Everytin'' dat made ya a troll hero, mon!',12,0,100,0,0,0,29407,'special_surprise SAY_EXEC_NOREM_9'),
(29061,27,0,'A pact was made, $g brother:sister;! We vowed vengeance against the Lich King! For what he had done to us! We battled the Scourge as Forsaken, pushing them back into the Plaguelands and freeing Tirisifal! You and I were champions of the Forsaken!',12,0,100,0,0,0,29398,'special_surprise SAY_EXEC_THINK_1'),
(29061,28,0,'You must remember the splendor of life, $g brother:sister;. You were a champion of the kaldorei once! This isn''t you!',12,0,100,0,0,0,29328,'special_surprise SAY_EXEC_THINK_2'),
(29061,29,0,'Think, $n. Think back. Try and remember the majestic halls of Silvermoon City, where you were born. Remember the splendor of life, $g brother:sister;. You were a champion of the sin''dorei once! This isn''t you.',12,0,100,0,0,0,29374,'special_surprise SAY_EXEC_THINK_3'),
(29061,30,0,'Think, $n. Think back. Try and remember the proud mountains of Argus, where you were born. Remember the splendor of life, $g brother:sister;. You were a champion of the draenei once! This isn''t you.',12,0,100,0,0,0,29362,'special_surprise SAY_EXEC_THINK_4'),
(29061,31,0,'Think, $n. Think back. Try and remember the snow capped mountains o'' Dun Morogh! Ye were born there, $g lad:lass;. Remember the splendor o'' life, $n! Ye were a champion o'' the dwarves once! This isn''t ye!',12,0,100,0,0,0,29340,'special_surprise SAY_EXEC_THINK_5'),
(29061,32,0,'Think, $n. Think back. Try and remember Gnomeregan before those damned troggs! Remember the feel of an arclight spanner, $g brother:sister;. You were a champion of gnome-kind once! This isn''t you.',12,0,100,0,0,0,29352,'special_surprise SAY_EXEC_THINK_6'),
(29061,33,0,'Think, $n. Think back. Try and remember the hills and valleys of Elwynn, where you were born. Remember the splendor of life, $g brother:sister;. You were a champion of the Alliance once! This isn''t you.',12,0,100,0,0,0,29315,'special_surprise SAY_EXEC_THINK_7'),
(29061,34,0,'Think, $n. Think back. Try and remember Durotar, $g brother:sister;! Remember the sacrifices our heroes made so that we could be free of the blood curse. Harken back to the Valley of Trials, where we were reborn into a world without demonic influence. We found the splendor of life, $n. Together! This isn''t you. You were a champion of the Horde once!',12,0,100,0,0,0,29388,'special_surprise SAY_EXEC_THINK_8'),
(29061,35,0,'Think, $n. Think back. Try and remember the rolling plains of Mulgore, where you were born. Remember the splendor of life, $g brother:sister;. You were a champion of the tauren once! This isn''t you.',12,0,100,0,0,0,29294,'special_surprise SAY_EXEC_THINK_9'),
(29061,36,0,'TINK, $n. Tink back, mon! We be Darkspear, mon! Bruddas and sistas! Remember when we fought da Zalazane and done took he head and freed da Echo Isles? MON! TINK! You was a champion of da Darkspear trolls!',12,0,100,0,0,0,29408,'special_surprise SAY_EXEC_THINK_10'),
(29061,37,0,'Listen to me, $n. You must fight against the Lich King''s control. He is a monster that wants to see this world - our world - in ruin. Don''t let him use you to accomplish his goals. You were once a hero and you can be again. Fight, damn you! Fight his control!',12,0,100,0,0,0,29389,'special_surprise SAY_EXEC_LISTEN_1'),
(29061,38,0,'Listen to me, $n. Ye must fight against the Lich King''s control. He''s a monster that wants to see this world - our world - in ruin. Don''t let him use ye to accomplish his goals. Ye were once a hero and ye can be again. Fight, damn ye! Fight his control!',12,0,100,0,0,0,29341,'special_surprise SAY_EXEC_LISTEN_2'),
(29061,39,0,'Listen to me, $n. You must fight against the Lich King''s control. He is a monster that wants to see this world - our world - in ruin. Don''t let him use you to accomplish his goals. You were once a hero and you can be again. Fight, damn you! Fight his control!',12,0,100,0,0,0,29329,'special_surprise SAY_EXEC_LISTEN_3'),
(29061,40,0,'Listen ta me, $g brudda:sista;. You must fight against da Lich King''s control. He be a monster dat want ta see dis world - our world - be ruined. Don''t let he use you ta accomplish he goals. You be a hero once and you be a hero again! Fight it, mon! Fight he control!',12,0,100,0,0,0,29409,'special_surprise SAY_EXEC_LISTEN_4'),
(29061,42,0,'There... There''s no more time for me. I''m done for. Finish me off, $n. Do it or they''ll kill us both. $n... Remember Silvermoon. This world is worth saving.',12,0,100,0,0,0,29376,'special_surprise SAY_EXEC_TIME_1'),
