(29070,4,0,'Well this son o'' Ironforge would like...',12,0,100,0,0,0,29336,'special_surprise SAY_EXEC_PROG_2'),
(29070,5,0,'Ironic, isn''t it? To be killed...',12,0,100,0,0,0,29394,'special_surprise SAY_EXEC_PROG_3'),
(29070,6,0,'If you''d allow me just one...',12,0,100,0,0,0,29348,'special_surprise SAY_EXEC_PROG_4'),
(29070,7,0,'I''d like to stand for...',12,0,100,0,0,0,29323,'special_surprise SAY_EXEC_PROG_5'),
