INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextID`,`comment`) VALUES
(29053,41,0,'What''s going on in there? What''s taking so long, $n?',14,0,100,0,0,0,29382,'special_surprise SAY_PLAGUEFIST'),
(29071,0,0,'Come to finish the job, have you?',12,0,100,0,0,0,29393,'special_surprise SAY_EXEC_START_1'),
(29071,1,0,'Come to finish the job, have ye?',12,0,100,0,0,0,29335,'special_surprise SAY_EXEC_START_2'),
(29071,2,0,'Come ta finish da job, mon?',12,0,100,0,0,0,29403,'special_surprise SAY_EXEC_START_3'),
(29071,3,0,'You''ll look me in the eyes when...',12,0,100,0,0,0,29369,'special_surprise SAY_EXEC_PROG_1'),
(29071,4,0,'Well this son o'' Ironforge would like...',12,0,100,0,0,0,29336,'special_surprise SAY_EXEC_PROG_2'),
